# Fails if the list of files on standard input (a directory listing or the contents of a zip, deb, rpm, pkg.tar.zst or pkg)
# is missing a license file of BlitzLLVM or of a dependency that is part of the bundle. Usage: <command listing files> | check-licenses.sh <name> [required-licenses.txt]
# A package that uses the system's libraries does not ship their licenses: the build writes the list of those that it does to required-licenses.txt
# in the build directory, which is passed as the second argument (the licenses of the sample programs are always checked).
set -u
name="${1:-bundle}"
listing="$(cat)"
required=(
	BlitzLLVM/LICENSE.adoc
	SDL3/LICENSE.txt
	SDL3_image/LICENSE.txt
	SDL3_image/optional/LICENSE.dav1d.txt
	SDL3_image/optional/LICENSE.avif.txt
	SDL3_image/optional/LICENSE.jxl.txt
	SDL3_image/optional/LICENSE.webp.txt
	SDL3_mixer/LICENSE.txt
	SDL3_mixer/optional/LICENSE.opus.txt
	SDL3_mixer/optional/LICENSE.opusfile.txt
	SDL3_mixer/optional/LICENSE.ogg-vorbis.txt
	FFmpeg/COPYING.LGPLv2.1
	Vulkan-Headers/LICENSE.md
	stb/LICENSE
	VulkanMemoryAllocator/LICENSE.txt
	SMAA/LICENSE
	Blitz3D/LICENSE.TXT
	BlitzPlus/LICENSE.TXT
)
if [[ -n "${2:-}" ]]; then
	# A missing or empty list would silently reduce the check to the two sample licenses, so it fails instead.
	if [[ ! -s "$2" ]]; then
		echo "MISSING  $name: the list of required licenses '$2' is missing or empty" >&2
		exit 1
	fi
	# The licenses of the sample programs are shipped whatever the libraries are.
	mapfile -t required < <(grep -v '^$' "$2"; printf '%s\n' Blitz3D/LICENSE.TXT BlitzPlus/LICENSE.TXT)
fi
status=0
for file in "${required[@]}"; do
	if grep -Eq "(^|/)licenses/(blitzllvm/)?${file//./\\.}\$" <<<"$listing"; then
		echo "ok       $name: licenses/$file"
	else
		echo "MISSING  $name: licenses/$file"
		status=1
	fi
done
exit $status
